function exactStackMap(){
  const pattern=layerPattern;const units=[];let i=0,anchor=0;
  while(i<pattern.length){
    if(pattern.slice(i,i+3)==='M*E'){units.push({anchor:++anchor,start:i+1,end:i+3,count:1});i+=3;}
    else {const start=i;while(pattern.slice(i,i+2)==='ME'){i+=2;}if(i===start)throw new Error('Unexpected hybrid pattern');units.push({start:start+1,end:i,count:(i-start)/2});}
  }
  const blocks=units.map((u,index)=>{const row=Math.floor(index/3),column=row%2?2-index%3:index%3;return diagramBlock('u'+index,u.anchor?'Attention anchor '+u.anchor:'Mamba–MoE pairs',`Layers ${u.start}–${u.end}${u.anchor?'':' · repeat '+u.count+'×'}`,28+column*319,71+row*169,277,127,u.anchor?'attention-anchor':'hybrid-pair',u.anchor?'blue':'mint',u.anchor?'anchor':'pair',{badge:u.anchor?'':u.count+'×'});});
  return {width:972,height:1107,title:'The exact 88-layer backbone',description:'An expanded version of the repeating groups. Read along the arrows.',blocks,edges:blocks.slice(1).map((b,index)=>diagramEdge(blocks[index].key,b.key,{fromPort:Math.floor(index/3)===Math.floor((index+1)/3)?(Math.floor(index/3)%2?'left':'right'):'bottom',toPort:Math.floor(index/3)===Math.floor((index+1)/3)?(Math.floor(index/3)%2?'right':'left'):'top'})),caption:'Each green group repeats a Mamba → LatentMoE pair. Each blue group is Mamba → attention → LatentMoE. Expanding these groups gives exactly 40 Mamba, 40 expert and 8 attention layers.'};
}

function getArchitectureMap(id){
  if(id==='stack')return exactStackMap();
  if(architectureMaps[id])return architectureMaps[id];
  const aliases={};
  if(aliases[id])return {...architectureMaps[aliases[id]],title:nodes[id].label,description:nodes[id].takeaway};
  const n=nodes[id];
  const steps=n.flow||[[n.label,'Open this concept'],...(n.children||[]).map(key=>[nodes[key].label,nodes[key].takeaway])];
  if(steps.length===1)steps.push(['The mechanism',n.takeaway]);
  const targets=n.diagramTargets||(n.flow?null:[id,...(n.children||[])]);
  const height=Math.max(580,steps.length*184+65);
  const blocks=steps.map((s,i)=>diagramBlock('step'+i,s[0],s[1],190,38+i*184,390,132,targets?.[i]||id,n.color||'mint',i===0?'embedding':'',{info:n.sections[Math.min(i,n.sections.length-1)][1]}));
  return {width:770,height,title:n.label,description:n.takeaway,blocks,edges:blocks.slice(1).map((b,i)=>diagramEdge(blocks[i].key,b.key,{color:n.color,dashed:!n.flow,label:!n.flow?'explore this connection':undefined})),caption:n.flow?n.takeaway:'Dashed links are concept connections. Open a block for its explanation or explore the linked idea.'};
}

function svgLines(text,x,y,size=22,color='#e6efff',maxChars=32,lineHeight=size*1.2){
  const lines=Array.isArray(text)?text:String(text).split(' ').reduce((result,word)=>{if(result.length&&result[result.length-1].length+word.length+1<=maxChars)result[result.length-1]+=' '+word;else result.push(word);return result;},[]);
  return `<text x="${x}" y="${y}" fill="${color}" font-size="${size}" font-family="Space Grotesk, sans-serif">${lines.map((line,i)=>`<tspan x="${x}" dy="${i?lineHeight:0}">${svgEscape(line)}</tspan>`).join('')}</text>`;
}
function svgEscape(text){return String(text).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function diagramGlyph(kind,x,y,w,h,color){
  const c=diagramColor[color]||diagramColor.mint;const tile=(tx,ty,tw,th,opacity=.6)=>`<rect x="${tx}" y="${ty}" width="${tw}" height="${th}" rx="2.5" fill="${c}" opacity="${opacity}"/>`;
  if(!kind||h<19)return '';
  if(kind==='experts'){const columns=32,rows=16,gap=1.8,size=Math.min((w-(columns-1)*gap)/columns,(h-(rows-1)*1.3)/rows);const ww=size*columns+(columns-1)*gap;return Array.from({length:512},(_,i)=>tile(x+(w-ww)/2+(i%32)*(size+gap),y+Math.floor(i/32)*(size+1.3),size,size,(i*23+11)%512<22?.96:.19)).join('');}
  if(['embedding','state','cache'].includes(kind)){const columns=kind==='cache'?16:kind==='state'?8:24,rows=kind==='state'?3:2;const gap=4,tw=Math.min(19,(w-gap*(columns-1))/columns),th=Math.min(10,(h-5)/rows);return Array.from({length:columns*rows},(_,i)=>tile(x+i%columns*(tw+gap),y+Math.floor(i/columns)*(th+5),tw,th,.22+(i*17%71)/100)).join('');}
  if(['heads','queries','keys','values','mamba-heads'].includes(kind)){const count=kind==='mamba-heads'?128:kind==='keys'||kind==='values'?2:32,cols=count===2?2:16,gap=3,rows=count/cols,tw=Math.min(count===2?80:16,(w-(cols-1)*gap)/cols),th=Math.min(count===2?23:9,(h-(rows-1)*4)/rows);const xx=x+(w-(tw+gap)*cols)/2;return Array.from({length:count},(_,i)=>tile(xx+i%cols*(tw+gap),y+Math.floor(i/cols)*(th+4),tw,th,.65)).join('')+(kind==='heads'?`<path d="M ${x+w*.25} ${y+28} L ${x+w*.25} ${y+38} L ${x+w*.75} ${y+38} L ${x+w*.75} ${y+28}" stroke="${c}" fill="none" opacity=".55"/>`:'');}
  if(['matrix','causal'].includes(kind)){const size=Math.min(9,(h-7)/5),gap=2,xx=x+w/2-5*(size+gap)/2;return Array.from({length:25},(_,i)=>tile(xx+i%5*(size+gap),y+Math.floor(i/5)*(size+gap),size,size,kind==='causal'&&i%5>Math.floor(i/5)?.06:.3+(i*7%65)/100)).join('');}
  if(['compress','expand'].includes(kind)){const left=kind==='compress'?16:4,right=kind==='compress'?4:16;let s='';[left,right].forEach((count,side)=>{const start=x+side*w*.66;const tw=Math.min(5,(w*.34-count*2)/count);for(let i=0;i<count;i++)s+=tile(start+i*(tw+2),y+5+(i*13%12),tw,Math.max(10,h-19-(i*7%12)),.55);});return s+`<path d="M ${x+w*.39} ${y+h*.5} L ${x+w*.6} ${y+h*.5}" stroke="${c}" stroke-width="2" marker-end="url(#arrow-${color})"/>`;}
  if(['probabilities','mix'].includes(kind)){return [18,35,54,30,14].map((v,i)=>tile(x+w*.3+i*w*.08,y+h-v/60*h,w*.045,v/60*h,i===2?.92:.3)).join('');}
  if(['tokens','draft','verify','window','split','ids','control'].includes(kind)){const labels=kind==='tokens'?['The','sky','is','blue']:kind==='split'?['x','B','C','Δ','gate']:kind==='control'?['B','C','Δ']:kind==='ids'?['17','824','36','…']:kind==='window'?['t−3','t−2','t−1','t']:['is','bright',kind==='verify'?'✓':'…'];const gap=7,tw=(w-gap*(labels.length-1))/labels.length;return labels.map((l,i)=>`<rect x="${x+i*(tw+gap)}" y="${y}" width="${tw}" height="${Math.min(h,27)}" rx="5" fill="${c}" fill-opacity="${kind==='verify'&&i===2?.35:.12}" stroke="${c}" stroke-opacity=".35"/><text x="${x+i*(tw+gap)+tw/2}" y="${y+18}" text-anchor="middle" font-size="12" fill="${c}" font-family="DM Sans, sans-serif">${l}</text>`).join('');}
  if(['pair','anchor','layers'].includes(kind)){const colors=kind==='anchor'?['mint','blue','violet']:['mint','violet'];const gap=12,tw=(w-gap*(colors.length-1))/colors.length;return colors.map((cl,i)=>`<rect x="${x+i*(tw+gap)}" y="${y}" width="${tw}" height="${Math.min(h,25)}" rx="5" fill="${diagramColor[cl]}" fill-opacity=".2" stroke="${diagramColor[cl]}" stroke-opacity=".4"/><text x="${x+i*(tw+gap)+tw/2}" y="${y+17}" text-anchor="middle" font-size="12" fill="${diagramColor[cl]}" font-family="DM Sans, sans-serif">${cl==='mint'?'Mamba':cl==='blue'?'GQA':'MoE'}</text>`).join('');}
  if(kind==='activation'){const axisY=y+h-2,zeroX=x+w*.36,right=x+w*.87;return `<path d="M ${x+w*.12} ${axisY} H ${x+w*.91} M ${zeroX} ${y+2} V ${axisY}" fill="none" stroke="${c}" stroke-opacity=".25"/><path d="M ${x+w*.14} ${axisY} H ${zeroX} Q ${right-w*.17} ${axisY} ${right} ${y+2}" fill="none" stroke="${c}" stroke-width="2.8"/>`;}
  const symbols={sum:'+',norm:'RMS(x)',retain:'aₜ × memory',recurrence:'aₜhₜ₋₁ + Bₜxₜ',gate:'output × gate',router:'scores → top-22',shared:'4,096 → 5,376 → 4,096'};
  return svgLines(symbols[kind]||'→',x+w/2,y+Math.min(23,h),kind==='sum'?31:17,c,35).replace('<text ','<text text-anchor="middle" ');
}

function diagramNodeSVG(b){
  const c=diagramColor[b.color]||diagramColor.mint;const size=b.w<240?19:23;const maxChars=Math.floor((b.w-34)/(size*.53));const titleLines=Array.isArray(b.label)?b.label:String(b.label).split(' ').reduce((a,v)=>{if(a.length&&a.at(-1).length+v.length+1<=maxChars)a[a.length-1]+=' '+v;else a.push(v);return a;},[]);
  const titleY=b.y+31;const subtitleY=titleY+(titleLines.length-1)*size*1.18+24;const maxSub=Math.floor((b.w-34)/7.1);
  let subtitle=String(b.subtitle);const maxLength=b.h<95?maxSub:Math.min(maxSub*2,90);if(subtitle.length>maxLength)subtitle=subtitle.slice(0,maxLength-1).replace(/\s+\S*$/,'')+'…';
  const subLines=Math.ceil(subtitle.length/maxSub);const glyphY=subtitleY+(Math.min(2,subLines)-1)*16+12;const glyphH=b.y+b.h-glyphY-15;
  return `<g class="diagram-node" data-diagram-node="${b.key}" data-diagram-target="${b.target}" role="button" tabindex="0" aria-label="${svgEscape(b.label)}. ${svgEscape(b.subtitle)}. ${b.target?'Open this block.':'Show details.'}" style="--node-color:${c}"><title>${svgEscape(b.label)} · ${svgEscape(b.subtitle)}</title><rect class="node-shadow" x="${b.x}" y="${b.y+4}" width="${b.w}" height="${b.h}" rx="16" fill="#050b16" opacity=".45"/><rect class="node-bg" x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" rx="16" fill="url(#block-${b.color})" stroke="${c}" stroke-opacity=".48" stroke-width="1.5"/><rect x="${b.x+1}" y="${b.y+18}" width="3" height="${b.h-36}" rx="1.5" fill="${c}" opacity=".85"/>${svgLines(titleLines,b.x+19,titleY,size,'#e7f0ff',maxChars,size*1.18)}${svgLines(subtitle,b.x+19,subtitleY,13,'#a4b8d2',maxSub,16)}${diagramGlyph(b.glyph,b.x+19,glyphY,b.w-38,glyphH,b.color)}<circle class="node-enter-bg" cx="${b.x+b.w-16}" cy="${b.y+14}" r="8" fill="${c}" fill-opacity=".13"/><path d="M ${b.x+b.w-19} ${b.y+17} L ${b.x+b.w-13} ${b.y+11} M ${b.x+b.w-18} ${b.y+11} H ${b.x+b.w-13} V ${b.y+16}" fill="none" stroke="${c}" stroke-width="1.2"/>${b.badge?`<text x="${b.x+b.w-16}" y="${b.y+b.h-12}" text-anchor="end" font-size="12" font-family="DM Sans, sans-serif" fill="${c}">${b.badge}</text>`:''}</g>`;
}

function diagramPort(b,port){switch(port){case'left':return[b.x,b.y+b.h/2];case'right':return[b.x+b.w,b.y+b.h/2];case'top':return[b.x+b.w/2,b.y];default:return[b.x+b.w/2,b.y+b.h];}}
function roundedPolyline(points,radius=10){if(points.length===2)return `M ${points[0].join(' ')} L ${points[1].join(' ')}`;let path=`M ${points[0].join(' ')}`;for(let i=1;i<points.length-1;i++){const p=points[i-1],q=points[i],r=points[i+1],d1=Math.hypot(q[0]-p[0],q[1]-p[1]),d2=Math.hypot(r[0]-q[0],r[1]-q[1]),rad=Math.min(radius,d1/2,d2/2);const before=[q[0]-(q[0]-p[0])/d1*rad,q[1]-(q[1]-p[1])/d1*rad],after=[q[0]+(r[0]-q[0])/d2*rad,q[1]+(r[1]-q[1])/d2*rad];path+=` L ${before.join(' ')} Q ${q.join(' ')} ${after.join(' ')}`;}return path+` L ${points.at(-1).join(' ')}`;}
function diagramEdgeSVG(e,map,index){const a=map.blocks.find(b=>b.key===e.from),b=map.blocks.find(b=>b.key===e.to);const horizontal=Math.abs(a.x+a.w/2-b.x-b.w/2)>Math.abs(a.y+a.h/2-b.y-b.h/2);const from=e.fromPort||(horizontal?(a.x<b.x?'right':'left'):'bottom'),to=e.toPort||(horizontal?(a.x<b.x?'left':'right'):'top');const start=diagramPort(a,from),end=diagramPort(b,to);const points=e.points||[start,end];const c=e.color||'slate';const labelAt=e.labelAt||[(start[0]+end[0])/2,(start[1]+end[1])/2-9];const d=roundedPolyline(points);return `<g class="diagram-connection"><path d="${d}" fill="none" stroke="${diagramColor[c]}" stroke-opacity="${e.dashed ? 0.4 : 0.65}" stroke-width="2.1" ${e.dashed?'stroke-dasharray="5 7"':''} marker-end="url(#arrow-${c})"/>${!e.dashed?`<path class="connection-flow" d="${d}" fill="none" stroke="${diagramColor[c]}" stroke-width="3.4" stroke-linecap="round" stroke-dasharray="1 36" style="animation-delay:${index*-.37}s" opacity=".7"/>`:''}${e.label?`<text x="${labelAt[0]}" y="${labelAt[1]}" text-anchor="middle" font-size="13" font-family="DM Sans, sans-serif" fill="${diagramColor[c]}">${svgEscape(e.label)}</text>`:''}</g>`;}
function architectureSVG(map){
  const defs=Object.entries(diagramColor).map(([key,c])=>`<marker id="arrow-${key}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 1 1 L 9 5 L 1 9 Z" fill="${c}"/></marker><linearGradient id="block-${key}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c}" stop-opacity=".12"/><stop offset="1" stop-color="#111c2e" stop-opacity=".98"/></linearGradient>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${map.width}" height="${map.height}" viewBox="0 0 ${map.width} ${map.height}" class="architecture-svg" aria-label="${svgEscape(map.title)} architecture diagram"><defs>${defs}</defs>${(map.groups||[]).map(g=>`<g ${g.target?`role="button" tabindex="0" class="diagram-group-link" data-diagram-target="${g.target}" aria-label="Open ${svgEscape(g.label)}"`:''}><rect x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" rx="22" fill="${diagramColor[g.color||'slate']}" fill-opacity=".025" stroke="${diagramColor[g.color||'slate']}" stroke-opacity=".24" stroke-dasharray="4 6"/><text x="${g.x+18}" y="${g.y+25}" font-size="12" letter-spacing="1.1" font-family="DM Sans, sans-serif" fill="${diagramColor[g.color||'slate']}">${g.label}${g.target?' ↗':''}</text></g>`).join('')}${map.edges.map((e,i)=>diagramEdgeSVG(e,map,i)).join('')}${map.blocks.map(diagramNodeSVG).join('')}${(map.notes||[]).map(n=>svgLines(n.lines,n.x,n.y,14,diagramColor[n.color||'slate'],55,21)).join('')}</svg>`;
}

let architectureFullscreen=false;
function resetArchitectureFullscreen(){architectureFullscreen=false;document.body.classList.remove('explorer-focused');}
function renderArchitectureExplorer(id){
  const map=getArchitectureMap(id);const n=nodes[id];
  return `<section class="architecture-explorer${architectureFullscreen?' explorer-expanded':''}" data-map="${id}" aria-label="Interactive architecture explorer"><div class="explorer-toolbar"><div class="explorer-location"><span class="map-symbol" aria-hidden="true">⌘</span><a href="#overview">Architecture</a>${id!=='overview'?`<span>/</span><span>${svgEscape(n.label)}</span>`:''}</div><div class="explorer-tools"><button type="button" data-map-action="out" aria-label="Zoom out" title="Zoom out">−</button><output id="map-zoom" aria-live="polite">100%</output><button type="button" data-map-action="in" aria-label="Zoom in" title="Zoom in">+</button><span class="tool-divider"></span><button type="button" data-map-action="fit" aria-label="Fit the whole diagram" title="Fit diagram">Fit</button><button type="button" data-map-action="expand" aria-label="Expand diagram to full screen" title="Full screen">⛶</button><button type="button" data-map-action="glossary" aria-label="Open glossary" title="Glossary">A–Z</button></div></div><div class="explorer-stage" tabindex="0" role="region" aria-label="${svgEscape(map.title)}. Click a block to open it. Use the zoom buttons, drag to pan, or pinch to zoom."><div class="diagram-world" style="width:${map.width}px;height:${map.height}px">${architectureSVG(map)}</div><div class="explorer-coordinates" aria-hidden="true">N3 / ${id==='overview'?'SYSTEM':id.toUpperCase()}</div><div class="explorer-gesture-hint">Drag to pan <span>·</span> Scroll or pinch to zoom</div><div class="diagram-inspector" id="diagram-inspector" hidden aria-live="polite"></div></div><div class="explorer-bottom"><div><span class="explorer-status-dot"></span><strong>${id==='overview'?'The whole model':'Open a block to keep exploring'}</strong><p>${svgEscape(map.caption)}</p></div>${id!=='overview'?`<button type="button" class="map-example-button" data-map-action="example">${n.sim&&!n.flow?'Animate an example':'See the step-by-step flow'} ↓</button>`:'<a class="map-example-button" href="#stack">Expand all 88 layers ↗</a>'}</div></section>`;
}

let disposeArchitectureExplorer=()=>{};
function teardownArchitectureExplorer(){disposeArchitectureExplorer();disposeArchitectureExplorer=()=>{};}
function setupArchitectureExplorer(id){
  const root=document.querySelector('.architecture-explorer');if(!root)return;const stage=root.querySelector('.explorer-stage'),world=root.querySelector('.diagram-world'),map=getArchitectureMap(id);const listeners=[];let frame=0,navigationTimer=0,resizeObserver;let view={scale:1,x:0,y:0},fitScale=1,expanded=architectureFullscreen;const pointers=new Map();let gesture=null,lastDrag=0;
  if(expanded){root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');document.body.classList.add('explorer-focused');root.querySelector('[data-map-action="expand"]').setAttribute('aria-label','Exit full screen');}
  const on=(el,event,handler,options)=>{el.addEventListener(event,handler,options);listeners.push(()=>el.removeEventListener(event,handler,options));};
  const dimensions=()=>{const rect=stage.getBoundingClientRect();return{width:rect.width||640,height:rect.height||620,left:rect.left,top:rect.top};};
  const apply=()=>{world.style.transform=`translate(${view.x}px, ${view.y}px) scale(${view.scale})`;stage.dataset.scale=view.scale;stage.dataset.panX=view.x;stage.dataset.panY=view.y;root.querySelector('#map-zoom').textContent=Math.round(view.scale/fitScale*100)+'%';};
  const fit=()=>{const d=dimensions();fitScale=Math.min(1,(d.width-34)/map.width,(d.height-32)/map.height);view={scale:fitScale,x:(d.width-map.width*fitScale)/2,y:(d.height-map.height*fitScale)/2};apply();};
  const zoom=(factor,x,y)=>{const d=dimensions();x=x??d.width/2;y=y??d.height/2;const next=Math.min(fitScale*5,Math.max(fitScale*.55,view.scale*factor));const ratio=next/view.scale;view={scale:next,x:x-(x-view.x)*ratio,y:y-(y-view.y)*ratio};apply();};
  const focusBlock=(block)=>{const d=dimensions();const scale=Math.min(fitScale*2.4,d.width/(block.w+90),d.height/(block.h+100));view={scale,x:d.width/2-(block.x+block.w/2)*scale,y:d.height/2-(block.y+block.h/2)*scale};world.classList.add('camera-transition');apply();};
  const inspect=(block)=>{const panel=root.querySelector('#diagram-inspector');panel.hidden=false;panel.innerHTML=`<div><span class="eyebrow" style="color:${diagramColor[block.color]}">INSIDE THIS OPERATION</span><h3>${svgEscape(block.label)}</h3><p>${svgEscape(block.info||nodes[block.target]?.takeaway||map.caption)}</p></div><button class="inspector-close" type="button" aria-label="Close block details">×</button>`;panel.querySelector('button').addEventListener('click',()=>{panel.hidden=true;[...root.querySelectorAll('[data-diagram-node]')].find(el=>el.dataset.diagramNode===block.key)?.focus?.({preventScroll:true});});root.querySelectorAll('[data-diagram-node]').forEach(e=>e.classList.toggle('selected',e.dataset.diagramNode===block.key));};
  const open=(el)=>{const target=el.dataset.diagramTarget,block=map.blocks.find(b=>b.key===el.dataset.diagramNode);if(!target||target===id){if(block)inspect(block);return;}if(block&&!motionPaused)focusBlock(block);clearTimeout(navigationTimer);navigationTimer=setTimeout(()=>{location.hash=target;},motionPaused?0:200);};
  on(stage,'click',event=>{if(Date.now()-lastDrag<160){event.preventDefault();return;}const el=event.target.closest('[data-diagram-target]');if(el)open(el);});
  on(stage,'keydown',event=>{const el=event.target.closest('[data-diagram-target]');if(el&&(event.key==='Enter'||event.key===' ')){event.preventDefault();open(el);return;}if(event.target===stage){if(event.key==='+'||event.key==='='){event.preventDefault();zoom(1.25);}if(event.key==='-'){event.preventDefault();zoom(.8);}if(event.key==='0'){event.preventDefault();fit();}const delta={ArrowLeft:[35,0],ArrowRight:[-35,0],ArrowUp:[0,35],ArrowDown:[0,-35]}[event.key];if(delta){event.preventDefault();view.x+=delta[0];view.y+=delta[1];apply();}}});
  on(stage,'wheel',event=>{if(event.target.closest('.diagram-inspector'))return;event.preventDefault();world.classList.remove('camera-transition');const d=dimensions();zoom(Math.exp(-Math.max(-100,Math.min(100,event.deltaY))*.004),event.clientX-d.left,event.clientY-d.top);},{passive:false});
  const startGesture=()=>{const entries=[...pointers.values()];if(entries.length===1)gesture={type:'pan',point:entries[0],view:{...view},moved:false};if(entries.length>=2){const a=entries[0],b=entries[1];gesture={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y),view:{...view},center:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},moved:true};}};
  on(stage,'pointerdown',event=>{if(event.target.closest('.diagram-inspector'))return;if(event.pointerType==='mouse'&&event.button!==0)return;world.classList.remove('camera-transition');pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(!event.target.closest('[data-diagram-target]')||pointers.size>1){for(const pointerId of pointers.keys())stage.setPointerCapture?.(pointerId);}startGesture();});
  on(stage,'pointermove',event=>{if(!pointers.has(event.pointerId)||!gesture)return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});const entries=[...pointers.values()];if(gesture.type==='pan'&&entries.length===1){const dx=event.clientX-gesture.point.x,dy=event.clientY-gesture.point.y;if(Math.hypot(dx,dy)>5)gesture.moved=true;if(gesture.moved){stage.setPointerCapture?.(event.pointerId);view={...gesture.view,x:gesture.view.x+dx,y:gesture.view.y+dy};stage.classList.add('dragging');apply();}}else if(entries.length>=2){const a=entries[0],b=entries[1],d=dimensions(),center={x:(a.x+b.x)/2-d.left,y:(a.y+b.y)/2-d.top},ratio=Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,gesture.distance),scale=Math.max(fitScale*.55,Math.min(fitScale*5,gesture.view.scale*ratio)),r=scale/gesture.view.scale;view={scale,x:center.x-(gesture.center.x-d.left-gesture.view.x)*r,y:center.y-(gesture.center.y-d.top-gesture.view.y)*r};apply();}});
  const endPointer=event=>{if(gesture?.moved)lastDrag=Date.now();pointers.delete(event.pointerId);if(stage.hasPointerCapture?.(event.pointerId))stage.releasePointerCapture?.(event.pointerId);stage.classList.remove('dragging');gesture=null;if(pointers.size)startGesture();};on(stage,'pointerup',endPointer);on(stage,'pointercancel',endPointer);
  const toggleExpand=()=>{expanded=!expanded;architectureFullscreen=expanded;if(expanded){root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');}else{root.removeAttribute('role');root.removeAttribute('aria-modal');}root.classList.toggle('explorer-expanded',expanded);document.body.classList.toggle('explorer-focused',expanded);root.querySelector('[data-map-action="expand"]').setAttribute('aria-label',expanded?'Exit full screen':'Expand diagram to full screen');cancelAnimationFrame(frame);frame=requestAnimationFrame(fit);};
  on(root,'click',event=>{const action=event.target.closest('[data-map-action]')?.dataset.mapAction;if(!action)return;if(action==='in')zoom(1.25);if(action==='out')zoom(.8);if(action==='fit'){world.classList.add('camera-transition');fit();}if(action==='expand')toggleExpand();if(action==='glossary')toggleGlossary(true);if(action==='example'){if(expanded)toggleExpand();const bench=document.querySelector('.visual-workbench');if(bench){bench.open=true;bench.scrollIntoView({block:'start',behavior:motionPaused?'instant':'smooth'});bench.querySelector('summary').focus({preventScroll:true});}}});
  on(document,'keydown',event=>{if(expanded&&event.key==='Tab'&&!document.querySelector('.glossary.open')){const focusable=[...root.querySelectorAll('button,a,[tabindex="0"]')].filter(el=>!el.closest('[hidden]'));const index=focusable.indexOf(document.activeElement);if(event.shiftKey&&index<=0){event.preventDefault();focusable.at(-1)?.focus();}else if(!event.shiftKey&&(index<0||index===focusable.length-1)){event.preventDefault();focusable[0]?.focus();}}if(event.key==='Escape'&&expanded&&!document.querySelector('.glossary.open'))toggleExpand();});
  if(typeof ResizeObserver!=='undefined'){resizeObserver=new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(fit);});resizeObserver.observe(stage);}fit();
  disposeArchitectureExplorer=()=>{listeners.forEach(remove=>remove());resizeObserver?.disconnect();clearTimeout(navigationTimer);cancelAnimationFrame(frame);document.body.classList.remove('explorer-focused');};
}
